INSERT OR IGNORE INTO projects (slug,name,tagline,body,repo_url,demo_url,domain_id,status,owner_id,created_at,updated_at) VALUES ('ai-3','AI游戏制作与塔防游戏','用AI技术制作了一个我的世界风格的塔防游戏','我们正在做一个塔防游戏，目前已经达到了游玩时长和效果都不错的程度。但是还有一些缺陷，如敌方小怪没有远程攻击效果、新手教程不够完善、内容还不够丰富，后续需要扩充内容、优化细节，我们需要招募有创新思想、热爱AI游戏编程的相关同学加入。',NULL,NULL,'creative','approved',COALESCE((SELECT id FROM members WHERE username='朱天野'), (SELECT MIN(id) FROM members)),'2026-09-07T10:28:20.144Z','2026-09-08T10:48:37.568Z');
