INSERT OR IGNORE INTO projects (slug,name,tagline,body,repo_url,demo_url,domain_id,status,owner_id,created_at,updated_at) VALUES ('p-de940a','不同干预行为对信息扩散触达率的影响','社会舆论仿真实验（项目08）第二组：在 SNAP 教学网络上，比较不干预、随机删点、按连接数优先删点三种干预对信息扩散触达率的影响；进一步检验规则+LLM 混合机制下结论是否稳健，并建立干预强度 k 与触达率的幂律剂量函数。','我们在研究什么 不同的干预行为，对信息扩散的触达率影响到底有多大？我们把问题拆成：自变量是干预方式，因变量是扩散结束时被触达人数占全体的比例（触达率）。','https://github.com/jialeliu-ai/project-8-2-opinion',NULL,NULL,'approved',COALESCE((SELECT id FROM members WHERE username='柳嘉乐'), (SELECT MIN(id) FROM members)),'2026-08-29T10:56:13.170Z','2026-08-31T06:15:46.599Z');
