INSERT OR IGNORE INTO projects (slug,name,tagline,body,repo_url,demo_url,domain_id,status,owner_id,created_at,updated_at) VALUES ('p-674d09','墨韵千年 叙事工坊','墨韵千年 · 叙事工坊，解决的是：  “故事如何让读者从‘看’变成‘参与’。”  它让创作者可以自由编织多线故事，让读者可以在选择中成为故事的一部分，让叙事从静态的文本走向动态的交互体验——无论是单人沉浸、双人对照，还是自定义扩展，都在同一','我们在做什么 墨韵千年是一个交互式叙事平台，让故事从「被阅读」变成「被体验」。读者通过选择推动剧情，体验单视角沉浸或双视角交错的不同叙事维度，在参与中成为故事的一部分。核心功能包括月光模式、古风音乐、书签系统、二维码分享和自定义故事上传。 进展到哪了 叙事引擎核心功能已全部完成，一套剧示范剧本《雾港博物馆》已上线，Python工具集支持故事数据生成与验证。下一步将建设多剧本库、迭代用户体验、搭建社区内容生态。   墨韵千年」不只是一款产品，它是一个开放的叙事生态。 我们相信：故事不应该只有一种讲法。当读者成为选择者，当叙事成为交互，故事就有了新的生命。无论你是创作者、开发者还是设计师，这里都有你的一席之地。 欢迎加入，一起书写下一个千年。',NULL,NULL,'creative','approved',COALESCE((SELECT id FROM members WHERE username='高恺齐'), (SELECT MIN(id) FROM members)),'2026-08-27T15:23:40.275Z','2026-08-28T09:50:24.216Z');
